SELECT Company_Claim_Number
FROM Claim
WHERE Claim_Close_Date BETWEEN '2019-01-01' AND '2019-12-31';

SELECT cp.Claim_Amount 
FROM Expense_Payment ep
JOIN Claim_Amount cp ON ep.Claim_Amount_Identifier = cp.Claim_Amount_Identifier;

SELECT Claim_Amount_Identifier, Claim_Amount 
FROM Expense_Reserve 
WHERE Claim_Amount_Identifier IN (SELECT Claim_Amount_Identifier FROM Claim_Amount);

SELECT Claim_Amount_Identifier, Claim_Amount
FROM Claim_Amount
WHERE Claim_Amount_Identifier IN (SELECT Claim_Amount_Identifier FROM Loss_Payment);

SELECT Company_Claim_Number
FROM Claim
WHERE Claim_Close_Date BETWEEN '2019-01-01' AND '2019-12-31';

SELECT Policy_Policy_Number, Policy_Effective_Date, Policy_Expiration_Date, Premium.Policy_Amount
FROM Policy
JOIN Premium ON Policy.Policy_Identifier = Premium.Policy_Amount_Identifier;

